# Generated by OmopViewer 0.8.0
# Be careful editing this file

server <- function(input, output, session) {
  # summary ----
  output$summary_cdm_name <- shinyTree::renderTree(summaryCdmName(data))
  output$summary_packages <- shinyTree::renderTree(summaryPackages(data))
  output$summary_min_cell_count <- shinyTree::renderTree(summaryMinCellCount(data))
  output$summary_panels <- shinyTree::renderTree(summaryPanels(data))
  # download raw data -----
  output$download_raw <- shiny::downloadHandler(
    filename = "results.csv",
    content = function(file) {
      data |>
        omopgenerics::bind() |>
        omopgenerics::exportSummarisedResult(
          fileName = file, logFile = NULL, logSqlPath = NULL
        )
    }
  )
  # render state ----
  renderState <- shiny::reactiveValues(
    summarise_omop_snapshot = "initial",
    summarise_clinical_records = "initial",
    summarise_trend = "initial",
    summarise_log_file = "initial",
    summarise_table = "initial",
    summarise_log_sql = "initial"
  )


  # summarise_omop_snapshot -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_omop_snapshot == "rendered") {
      renderState$summarise_omop_snapshot <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_omop_snapshot_cdm_name,
      input$summarise_omop_snapshot_variable_name,
      ignoreInit = TRUE
    )
  output$update_message_summarise_omop_snapshot <- shiny::renderUI({
    switch(renderState$summarise_omop_snapshot,
      initial = updateInitialMessage,
      stale = updateMessage,
      rendered = NULL
    )
  })
  shiny::observeEvent(input$update_summarise_omop_snapshot,
    {
      renderState$summarise_omop_snapshot <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_omop_snapshot data
  getSummariseOmopSnapshotData <- shiny::eventReactive(input$update_summarise_omop_snapshot,
    {
      data[["summarise_omop_snapshot"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_omop_snapshot_cdm_name,
          .data$variable_name %in% input$summarise_omop_snapshot_variable_name
        )
    },
    ignoreInit = TRUE
  )
  getSummariseOmopSnapshotTable <- shiny::reactive({
    getSummariseOmopSnapshotData() |>
      OmopSketch::tableOmopSnapshot(
        header = input$summarise_omop_snapshot_table_header,
        groupColumn = input$summarise_omop_snapshot_table_group_column,
        hide = input$summarise_omop_snapshot_table_hide
      )
  })
  output$summarise_omop_snapshot_table <- gt::render_gt({
    getSummariseOmopSnapshotTable()
  })
  output$summarise_omop_snapshot_table_download <- shiny::downloadHandler(
    filename = paste0("table_snapshot.", input$summarise_omop_snapshot_table_format),
    content = function(file) {
      gt::gtsave(getSummariseOmopSnapshotTable(), file)
    }
  )

  # summarise_clinical_records -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_clinical_records == "rendered") {
      renderState$summarise_clinical_records <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_clinical_records_cdm_name,
      input$summarise_clinical_records_omop_table,
      input$summarise_clinical_records_variable_name,
      input$summarise_clinical_records_estimate_name,
      ignoreInit = TRUE
    )
  output$update_message_summarise_clinical_records <- shiny::renderUI({
    switch(renderState$summarise_clinical_records,
      initial = updateInitialMessage,
      stale = updateMessage,
      rendered = NULL
    )
  })
  shiny::observeEvent(input$update_summarise_clinical_records,
    {
      renderState$summarise_clinical_records <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_clinical_records data
  getSummariseClinicalRecordsData <- shiny::eventReactive(input$update_summarise_clinical_records,
    {
      data[["summarise_clinical_records"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_clinical_records_cdm_name,
          .data$variable_name %in% input$summarise_clinical_records_variable_name,
          .data$estimate_name %in% input$summarise_clinical_records_estimate_name
        ) |>
        omopgenerics::filterGroup(.data$omop_table %in% input$summarise_clinical_records_omop_table)
    },
    ignoreInit = TRUE
  )
  getSummariseClinicalRecordsTable <- shiny::reactive({
    getSummariseClinicalRecordsData() |>
      OmopSketch::tableClinicalRecords(
        header = input$summarise_clinical_records_table_header,
        groupColumn = input$summarise_clinical_records_table_group_column,
        hide = input$summarise_clinical_records_table_hide
      )
  })
  output$summarise_clinical_records_table <- gt::render_gt({
    getSummariseClinicalRecordsTable()
  })
  output$summarise_clinical_records_table_download <- shiny::downloadHandler(
    filename = paste0("table_clinical_records.", input$summarise_clinical_records_table_format),
    content = function(file) {
      gt::gtsave(getSummariseClinicalRecordsTable(), file)
    }
  )

  # summarise_trend -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_trend == "rendered") {
      renderState$summarise_trend <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_trend_cdm_name,
      input$summarise_trend_omop_table,
      input$summarise_trend_time_interval,
      input$summarise_trend_has_udi,
      input$summarise_trend_interval,
      input$summarise_trend_mapped_to_standard,
      input$summarise_trend_type,
      input$summarise_trend_variable_name,
      input$summarise_trend_estimate_name,
      ignoreInit = TRUE
    )
  output$update_message_summarise_trend <- shiny::renderUI({
    switch(renderState$summarise_trend,
      initial = updateInitialMessage,
      stale = updateMessage,
      rendered = NULL
    )
  })
  shiny::observeEvent(input$update_summarise_trend,
    {
      renderState$summarise_trend <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_trend data
  getSummariseTrendData <- shiny::eventReactive(input$update_summarise_trend,
    {
      data[["summarise_trend"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_trend_cdm_name,
          .data$variable_name %in% input$summarise_trend_variable_name,
          .data$estimate_name %in% input$summarise_trend_estimate_name
        ) |>
        omopgenerics::filterGroup(.data$omop_table %in% input$summarise_trend_omop_table) |>
        omopgenerics::filterAdditional(.data$time_interval %in% input$summarise_trend_time_interval) |>
        omopgenerics::filterSettings(
          .data$has_udi %in% input$summarise_trend_has_udi,
          .data$interval %in% input$summarise_trend_interval,
          .data$mapped_to_standard %in% input$summarise_trend_mapped_to_standard,
          .data$type %in% input$summarise_trend_type
        )
    },
    ignoreInit = TRUE
  )
  getSummariseTrendTable <- shiny::reactive({
    getSummariseTrendData() |>
      OmopSketch::tableTrend(
        type = "reactable",
        header = input$summarise_trend_table_header,
        groupColumn = input$summarise_trend_table_group_column,
        hide = input$summarise_trend_table_hide
      )
  })
  output$summarise_trend_table <- reactable::renderReactable({
    getSummariseTrendTable()
  })
  output$summarise_trend_table_download <- shiny::downloadHandler(
    filename = "trends.csv",
    content = function(file) {
      getSummariseTrendTable() |>
        readr::write_csv(file = file)
    }
  )
  getSummariseTrendPlot <- shiny::reactive({
    getSummariseTrendData() |>
      OmopSketch::plotTrend(
        output = input$summarise_trend_plot_output,
        facet = input$summarise_trend_plot_facet,
        colour = input$summarise_trend_plot_colour
      )
  })
  output$summarise_trend_plot <- shiny::renderUI({
    tryCatch(
      {
        x <- getSummariseTrendPlot()
        renderInteractivePlot(x, input$summarise_trend_plot_interactive)
      },
      error = function(e) {
        if (inherits(e, "shiny.silent.error")) stop(e)
        shiny::div(class = "alert alert-danger text-white d-flex align-items-start gap-2", shiny::icon("triangle-exclamation", class = "mt-1"), shiny::div(class = "error-message", conditionMessage(e)))
      }
    )
  })
  output$summarise_trend_plot_download <- shiny::downloadHandler(
    filename = "plot_trend.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseTrendPlot(),
        width = as.numeric(input$summarise_trend_plot_width),
        height = as.numeric(input$summarise_trend_plot_height),
        units = input$summarise_trend_plot_units,
        dpi = as.numeric(input$summarise_trend_plot_dpi)
      )
    }
  )

  # summarise_log_file -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_log_file == "rendered") {
      renderState$summarise_log_file <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_log_file_cdm_name,
      input$summarise_log_file_variable_name,
      ignoreInit = TRUE
