  })
  shiny::observeEvent(input$update_summarise_log_file,
    {
      renderState$summarise_log_file <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_log_file data
  getSummariseLogFileData <- shiny::eventReactive(input$update_summarise_log_file,
    {
      data[["summarise_log_file"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_log_file_cdm_name,
          .data$variable_name %in% input$summarise_log_file_variable_name
        )
    },
    ignoreInit = TRUE
  )
  getSummariseLogFileTable <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "date_time") |>
      visOmopResults::visOmopTable(
        header = "cdm_name",
        hide = c("variable_level", "estimate_name")
      )
  })
  output$summarise_log_file_table <- gt::render_gt({
    getSummariseLogFileTable()
  })
  output$summarise_log_file_table_download <- shiny::downloadHandler(
    filename = paste0("table_log.", input$summarise_log_file_table_format),
    content = function(file) {
      gt::gtsave(getSummariseLogFileTable(), file)
    }
  )
  getSummariseLogFilePlot <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "elapsed_time") |>
      visOmopResults::barPlot(
        x = c("log_id", "variable_name"),
        y = "elapsed_time",
        colour = "cdm_name",
        position = input$summarise_log_file_plot_position
      )
  })
  output$summarise_log_file_plot <- shiny::renderUI({
    tryCatch(
      {
        x <- getSummariseLogFilePlot()
        renderInteractivePlot(x, input$summarise_log_file_plot_interactive)
      },
      error = function(e) {
        if (inherits(e, "shiny.silent.error")) stop(e)
        shiny::div(class = "alert alert-danger text-white d-flex align-items-start gap-2", shiny::icon("triangle-exclamation", class = "mt-1"), shiny::div(class = "error-message", conditionMessage(e)))
      }
    )
  })
  output$summarise_log_file_plot_download <- shiny::downloadHandler(
    filename = "plot_logs.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseLogFilePlot(),
        width = as.numeric(input$summarise_log_file_plot_width),
        height = as.numeric(input$summarise_log_file_plot_height),
        units = input$summarise_log_file_plot_units,
        dpi = as.numeric(input$summarise_log_file_plot_dpi)
      )
    }
  )

  # summarise_table -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_table == "rendered") {
      renderState$summarise_table <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_table_cdm_name,
      input$summarise_table_unique_device_id,
      input$summarise_table_variable_name,
      input$summarise_table_estimate_name,
      ignoreInit = TRUE
    )
  output$update_message_summarise_table <- shiny::renderUI({
    switch(renderState$summarise_table,
      initial = updateInitialMessage,
      stale = updateMessage,
      rendered = NULL
    )
  })
  shiny::observeEvent(input$update_summarise_table,
    {
      renderState$summarise_table <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_table data
  getSummariseTableData <- shiny::eventReactive(input$update_summarise_table,
    {
      data[["summarise_table"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_table_cdm_name,
          .data$variable_name %in% input$summarise_table_variable_name,
          .data$estimate_name %in% input$summarise_table_estimate_name
        ) |>
        omopgenerics::filterGroup(.data$unique_device_id %in% input$summarise_table_unique_device_id)
    },
    ignoreInit = TRUE
  )
  getSummariseTableTidy <- shiny::reactive({
    tidyDT(getSummariseTableData(), input$summarise_table_tidy_columns, input$summarise_table_tidy_pivot_estimates)
  })
  output$summarise_table_tidy <- DT::renderDT({
    getSummariseTableTidy()
  })
  output$summarise_table_tidy_download <- shiny::downloadHandler(
    filename = "tidy_results.csv",
    content = function(file) {
      getSummariseTableData() |>
        omopgenerics::tidy() |>
        readr::write_csv(file = file)
    }
  )
  getSummariseTableTable <- shiny::reactive({
    getSummariseTableData() |>
      simpleTable(
        header = input$summarise_table_table_header,
        group = input$summarise_table_table_group_column,
        hide = input$summarise_table_table_hide
      )
  })
  output$summarise_table_table <- gt::render_gt({
    getSummariseTableTable()
  })
  output$summarise_table_table_download <- shiny::downloadHandler(
    filename = paste0("table.", input$summarise_table_table_format),
    content = function(file) {
      gt::gtsave(getSummariseTableTable(), file)
    }
  )

  # summarise_log_sql -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_log_sql == "rendered") {
      renderState$summarise_log_sql <- "stale"
