      input$summarise_log_sql_log_id,
      input$summarise_log_sql_type,
      input$summarise_log_sql_name,
      input$summarise_log_sql_temporary,
      input$summarise_log_sql_overwrite,
      input$summarise_log_sql_variable_name,
      input$summarise_log_sql_estimate_name,
      input$summarise_log_sql_prefix,
      input$summarise_log_sql_schema,
      ignoreInit = TRUE
    )
  output$update_message_summarise_log_sql <- shiny::renderUI({
    switch(renderState$summarise_log_sql,
      initial = updateInitialMessage,
      stale = updateMessage,
