        ) |>
        omopgenerics::filterGroup(.data$log_id %in% input$summarise_log_sql_log_id) |>
        omopgenerics::filterStrata(
          .data$type %in% input$summarise_log_sql_type,
          .data$name %in% input$summarise_log_sql_name
        ) |>
        omopgenerics::filterAdditional(
          .data$temporary %in% input$summarise_log_sql_temporary,
          .data$overwrite %in% input$summarise_log_sql_overwrite
        ) |>
        omopgenerics::filterSettings(
          .data$prefix %in% input$summarise_log_sql_prefix,
          .data$schema %in% input$summarise_log_sql_schema
